using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;
[InitializeOnLoad]public static class CityMobileOptimizationBuild{
const string D="Assets/Scenes/Oasis/MobileOptimization",B="FinalEnvironmentRoadBackup/BeforeMobileOptimization",R="FinalEnvironmentRoadReview/MobileOptimization/";static Dictionary<Mesh,Mesh[]> cache=new Dictionary<Mesh,Mesh[]>();static Dictionary<string,GameObject> templates=new Dictionary<string,GameObject>();static StringBuilder log;static int lodCount,farCount,prefabCount,links;static long sourceTris,farTris;static HashSet<string> backups=new HashSet<string>();
static CityMobileOptimizationBuild(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityMobileOptimizationBuild.request"))return;File.Delete("CityMobileOptimizationBuild.request");try{Run();}catch(Exception e){File.WriteAllText(R+"Build.txt",(log==null?"":log.ToString())+"\nFAILED "+e);Debug.LogException(e);}}
public static void Backup(string p){if(!File.Exists(p)||!backups.Add(p))return;string dest=B+"/Assets/"+p;Directory.CreateDirectory(Path.GetDirectoryName(dest));if(!File.Exists(dest))File.Copy(p,dest);}
static bool Eligible(MeshFilter f){if(!f||!f.sharedMesh||!f.GetComponent<MeshRenderer>()||!f.gameObject.activeInHierarchy||f.GetComponentInParent<LODGroup>()||f.GetComponentInParent<Rigidbody>()||f.GetComponentsInChildren<LODGroup>(true).Length>0)return false;var r=f.GetComponent<MeshRenderer>();if(!r.enabled||!r.sharedMaterials.Any()||r.sharedMaterials.Any(m=>!m))return false;float span=Mathf.Max(r.bounds.size.x,r.bounds.size.y,r.bounds.size.z);if(span>170||span<.05f||CityMobileMeshReducer.Triangles(f.sharedMesh)<30)return false;string shader=r.sharedMaterial.shader.name.ToLowerInvariant(),name=r.sharedMaterial.name.ToLowerInvariant();if(name.Contains("road atlas")||name.Contains("png marking")||name=="pathways"||name.Contains("water")||name.Contains("sand")||name.Contains("shoreline")||shader.Contains("textmesh")||shader.Contains("parking")||name.Contains("hospital"))return false;return true;}
static Mesh[] Levels(Mesh m){Mesh[] v;if(cache.TryGetValue(m,out v))return v;v=new Mesh[2];string guid;long id;AssetDatabase.TryGetGUIDAndLocalFileIdentifier(m,out guid,out id);for(int level=1;level<=2;level++){if(CityMobileMeshReducer.Triangles(m)<250)continue;string path=D+"/Meshes/"+guid+"_"+id+"_LOD"+level+".asset";v[level-1]=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(v[level-1])continue;var reduced=CityMobileMeshReducer.Reduce(m,level);if(reduced){AssetDatabase.CreateAsset(reduced,path);v[level-1]=reduced;farCount++;}}if(v[0]&&v[1]&&CityMobileMeshReducer.Triangles(v[1])>=CityMobileMeshReducer.Triangles(v[0]))v[1]=null;cache.Add(m,v);log.AppendLine("MESH "+m.name+" base="+CityMobileMeshReducer.Triangles(m)+" mid="+(v[0]?CityMobileMeshReducer.Triangles(v[0]):0)+" far="+(v[1]?CityMobileMeshReducer.Triangles(v[1]):0));return v;}
static void CopyRenderer(MeshRenderer src,MeshRenderer dst){dst.sharedMaterials=src.sharedMaterials;dst.shadowCastingMode=src.shadowCastingMode;dst.receiveShadows=src.receiveShadows;dst.lightProbeUsage=src.lightProbeUsage;dst.reflectionProbeUsage=src.reflectionProbeUsage;dst.renderingLayerMask=src.renderingLayerMask;dst.allowOcclusionWhenDynamic=true;dst.motionVectorGenerationMode=src.motionVectorGenerationMode;dst.lightmapIndex=src.lightmapIndex;dst.lightmapScaleOffset=src.lightmapScaleOffset;dst.realtimeLightmapIndex=src.realtimeLightmapIndex;dst.realtimeLightmapScaleOffset=src.realtimeLightmapScaleOffset;}
static MeshRenderer Far(MeshFilter f,Mesh m,int level){var go=new GameObject("Mobile LOD"+level);go.transform.SetParent(f.transform,false);go.layer=f.gameObject.layer;go.AddComponent<MeshFilter>().sharedMesh=m;var mr=go.AddComponent<MeshRenderer>();CopyRenderer(f.GetComponent<MeshRenderer>(),mr);GameObjectUtility.SetStaticEditorFlags(go,StaticEditorFlags.OccludeeStatic);return mr;}
static bool AddLOD(MeshFilter f){if(!Eligible(f))return false;var mr=f.GetComponent<MeshRenderer>();var levels=Levels(f.sharedMesh);var entries=new List<LOD>();float span=Mathf.Max(mr.bounds.size.x,mr.bounds.size.y,mr.bounds.size.z);bool building=mr.sharedMaterial.name.StartsWith("Building")||span>28;float cull=building?.00015f:.001f;if(levels[0]){entries.Add(new LOD(.10f,new Renderer[]{mr}));if(levels[1]){entries.Add(new LOD(.04f,new Renderer[]{Far(f,levels[0],1)}));entries.Add(new LOD(cull,new Renderer[]{Far(f,levels[1],2)}));}else entries.Add(new LOD(cull,new Renderer[]{Far(f,levels[0],1)}));}else if(levels[1]){entries.Add(new LOD(.04f,new Renderer[]{mr}));entries.Add(new LOD(cull,new Renderer[]{Far(f,levels[1],2)}));}else entries.Add(new LOD(cull,new Renderer[]{mr}));var lod=f.gameObject.AddComponent<LODGroup>();lod.fadeMode=LODFadeMode.None;lod.SetLODs(entries.ToArray());lod.RecalculateBounds();lodCount++;sourceTris+=CityMobileMeshReducer.Triangles(f.sharedMesh);var last=entries.Last().renderers[0].GetComponent<MeshFilter>();farTris+=CityMobileMeshReducer.Triangles(last.sharedMesh);EditorUtility.SetDirty(lod);return true;}
static string LeafKey(MeshFilter f){string g;long id;AssetDatabase.TryGetGUIDAndLocalFileIdentifier(f.sharedMesh,out g,out id);return g+"_"+id+"_"+string.Join("_",f.GetComponent<MeshRenderer>().sharedMaterials.Select(m=>AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(m))));}
static GameObject Template(MeshFilter f){string key=LeafKey(f);GameObject asset;if(templates.TryGetValue(key,out asset))return asset;string path=D+"/Prefabs/Shared_"+key+".prefab";asset=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!asset){var go=new GameObject(f.name+" Shared Mobile Prop");go.AddComponent<MeshFilter>().sharedMesh=f.sharedMesh;var r=go.AddComponent<MeshRenderer>();CopyRenderer(f.GetComponent<MeshRenderer>(),r);go.layer=f.gameObject.layer;go.transform.localScale=f.transform.lossyScale;GameObjectUtility.SetStaticEditorFlags(go,GameObjectUtility.GetStaticEditorFlags(f.gameObject)&~StaticEditorFlags.BatchingStatic);AddLOD(go.GetComponent<MeshFilter>());asset=PrefabUtility.SaveAsPrefabAsset(go,path);UnityEngine.Object.DestroyImmediate(go);prefabCount++;}templates.Add(key,asset);return asset;}
static bool PlainLeaf(MeshFilter f){return f.transform.childCount==0&&f.GetComponents<Component>().All(c=>c is Transform||c is MeshFilter||c is MeshRenderer||c is Collider)&&!PrefabUtility.IsPartOfPrefabInstance(f.gameObject);}
static void ProcessContents(string path,bool garden){Backup(path);var content=PrefabUtility.LoadPrefabContents(path);try{var all=content.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh).ToArray();bool dirty=false;foreach(var f in all){bool plant=garden&&(f.name.StartsWith("GardenPlants_")||f.name.StartsWith("PortalIvy_")||f.name.StartsWith("Fountain_")||f.name.StartsWith("UtilityCovers_"));if(f.gameObject!=content&&(plant||Eligible(f))&&PlainLeaf(f)){var asset=Template(f);PrefabUtility.ConvertToPrefabInstance(f.gameObject,asset,new ConvertToPrefabInstanceSettings{objectMatchMode=ObjectMatchMode.ByHierarchy,changeRootNameToAssetName=false,recordPropertyOverridesOfMatches=true,componentsNotMatchedBecomesOverride=true,gameObjectsNotMatchedBecomesOverride=true},InteractionMode.AutomatedAction);links++;dirty=true;}else if(AddLOD(f))dirty=true;}if(dirty){PrefabUtility.SaveAsPrefabAsset(content,path);log.AppendLine("PREFAB UPDATED "+path);}}finally{PrefabUtility.UnloadPrefabContents(content);}}
static void Capture(Scene sc,string phase){var cap=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);cap.Invoke(null,new object[]{sc,new Vector3(-32,58,-351.9f),new Vector3(-115,36,-351.9f),"MobileOptimization/Hospital-"+phase});cap.Invoke(null,new object[]{sc,new Vector3(-62,32,230),new Vector3(-62,31,320),"MobileOptimization/Street-"+phase});cap.Invoke(null,new object[]{sc,new Vector3(222,39,295),new Vector3(222,31,255),"MobileOptimization/Coffee-"+phase});}
static void Run(){Directory.CreateDirectory(R);log=new StringBuilder();if(File.Exists(R+"Complete.txt"))throw new Exception("Optimization already applied; use verification instead of rebuilding.");var sc=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");Backup(sc.path);Capture(sc,"Before");CityMobileOptimizationMeasure.Write(sc,R+"Visibility-Before.csv");var original=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.sharedMesh).ToDictionary(f=>f,f=>f.sharedMesh);var rs=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).ToArray();var native=rs.Where(r=>r.GetComponent<MeshFilter>()&&Eligible(r.GetComponent<MeshFilter>())).GroupBy(r=>PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(r.gameObject)).Where(g=>!string.IsNullOrEmpty(g.Key)&&g.Key.StartsWith("Assets/Scenes/Oasis/3D/Prefeb/")).ToArray();foreach(var group in native){string path=group.Key;var asset=AssetDatabase.LoadAssetAtPath<GameObject>(path);var rootMesh=asset?asset.GetComponent<MeshFilter>():null;if(!rootMesh||group.Any(r=>r.GetComponent<MeshFilter>().sharedMesh!=rootMesh.sharedMesh))continue;ProcessContents(path,false);}
ProcessContents("Assets/Scenes/Oasis/FinalEnvironmentRoads/GardenUtilityAtlas/City Atlas Gardens and Utilities.prefab",true);ProcessContents("Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab",true);
foreach(var f in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).ToArray())if(f&&f.sharedMesh){if(PlainLeaf(f)&&Eligible(f)&&f.name.StartsWith("Fountain_")){PrefabUtility.ConvertToPrefabInstance(f.gameObject,Template(f),new ConvertToPrefabInstanceSettings{objectMatchMode=ObjectMatchMode.ByHierarchy,changeRootNameToAssetName=false,recordPropertyOverridesOfMatches=true},InteractionMode.AutomatedAction);links++;}else AddLOD(f);}
var after=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).ToArray();int staticCount=0;foreach(var r in after){if(r.GetComponentInParent<Rigidbody>())continue;var flags=GameObjectUtility.GetStaticEditorFlags(r.gameObject);flags&=~StaticEditorFlags.BatchingStatic;flags|=StaticEditorFlags.OccludeeStatic;string name=r.sharedMaterial?r.sharedMaterial.name:"";if(name.StartsWith("Building")&&r.bounds.size.y>5&&!r.name.StartsWith("Mobile LOD"))flags|=StaticEditorFlags.OccluderStatic;else flags&=~StaticEditorFlags.OccluderStatic;GameObjectUtility.SetStaticEditorFlags(r.gameObject,flags);r.allowOcclusionWhenDynamic=true;staticCount++;}foreach(var c in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)))c.useOcclusionCulling=true;
var used=after.SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct().ToArray();int duplicateSlots=0;foreach(var g in used.GroupBy(CityMobileOptimizationAudit.Signature).Where(g=>g.Count()>1)){var canonical=g.OrderBy(m=>AssetDatabase.GetAssetPath(m).Length).First();foreach(var r in after){var slots=r.sharedMaterials;bool dirty=false;for(int i=0;i<slots.Length;i++)if(slots[i]!=canonical&&g.Contains(slots[i])){slots[i]=canonical;duplicateSlots++;dirty=true;}if(dirty){r.sharedMaterials=slots;PrefabUtility.RecordPrefabInstancePropertyModifications(r);}}}foreach(var m in used){if(m.shader.name.Contains("TextMeshPro"))continue;Backup(AssetDatabase.GetAssetPath(m));m.enableInstancing=true;EditorUtility.SetDirty(m);}
foreach(var pair in original)if(pair.Key&&pair.Key.sharedMesh!=pair.Value)throw new Exception("Near source mesh changed: "+pair.Key.name);
AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);CityMobileOptimizationMeasure.Write(sc,R+"Visibility-After.csv");Capture(sc,"After");log.AppendLine("SUCCESS new LOD groups authored="+lodCount+" generated reduced meshes="+farCount+" reusable leaf prefabs="+prefabCount+" source prefab connections="+links+" duplicate material slots consolidated="+duplicateSlots+" static occlusion flags="+staticCount+" source triangles for authored groups="+sourceTris+" last-level triangles="+farTris+". Near mesh references unchanged. No meshes combined, no new materials or textures. Device FPS not measured.");File.WriteAllText(R+"Build.txt",log.ToString());File.WriteAllText(R+"Complete.txt","Saved "+DateTime.UtcNow.ToString("O"));}
}
